const ARRIVAL_STATEMENTS: Record<string, { kind: "log" | "set"; add_sql: string; del_sql: string | null }> = {
  resolved_call_edge: { kind: "set", add_sql: `INSERT OR IGNORE INTO "resolved_call_edge" ("caller_path", "caller_name", "callee_path", "callee_name") VALUES (?, ?, ?, ?)`, del_sql: `DELETE FROM "resolved_call_edge" WHERE "caller_path" = ? AND "caller_name" = ? AND "callee_path" = ? AND "callee_name" = ?` },
};

function arrival_statement(arrival: IArrivalRow): SqlStatement {
  const template = ARRIVAL_STATEMENTS[arrival.rel];
  if (template === undefined) {
    throw new Error(`flagship_flow_reach_over_batched_resolved_edges: tick received an arrival for undeclared rel '${arrival.rel}'`);
  }
  if (arrival.sign === "del") {
    if (template.kind === "log") {
      throw new Error(`flagship_flow_reach_over_batched_resolved_edges: retract from log rel '${arrival.rel}' (engine.pl retract_from_log)`);
    }
    if (template.del_sql === null) {
      throw new Error(`flagship_flow_reach_over_batched_resolved_edges: rel '${arrival.rel}' has no delete statement`);
    }
    return { sql: template.del_sql, args: bind_args(arrival.row) };
  }
  return { sql: template.add_sql, args: bind_args(arrival.row) };
}

function apply_arrivals(seam: ISqlSeam, arrivals: IArrivalBatch): Observable<unknown> {
  const statements: SqlStatement[] = arrivals.map(arrival_statement);
  return seam.runner.batch(seam.db, statements);
}

