function recompute_levels(seam: ISqlSeam): Observable<void> {
  const delete_sql = `DELETE FROM "flow_edge";
DELETE FROM "flow_reach"`;
  const insert_sql = `INSERT OR IGNORE INTO "flow_edge" ("from_path", "from_name", "to_path", "to_name") SELECT b0."caller_path", b0."caller_name", b0."callee_path", b0."callee_name" FROM "resolved_call_edge" b0;
INSERT OR IGNORE INTO "flow_reach" ("from_path", "from_name", "to_path", "to_name") SELECT b0."from_path", b0."from_name", b0."to_path", b0."to_name" FROM "flow_edge" b0;
INSERT OR IGNORE INTO "flow_reach" ("from_path", "from_name", "to_path", "to_name") SELECT b0."from_path", b0."from_name", b1."to_path", b1."to_name" FROM "flow_reach" b0, "flow_edge" b1 WHERE b1."from_path" = b0."to_path" AND b1."from_name" = b0."to_name"`;
  const count_sql = `SELECT (SELECT count(*) FROM "flow_edge") + (SELECT count(*) FROM "flow_reach")`;
  return seam.runner.executeMultiple(seam.db, delete_sql).pipe(
    map(() => -1),
    expand((prior_rows) => seam.runner.executeMultiple(seam.db, insert_sql).pipe(
      concatMap(() => seam.runner.scalar(seam.db, count_sql)),
      concatMap((rows) => (rows === prior_rows ? EMPTY : of(rows))),
    )),
    last(),
    map(() => undefined),
  );
}

function build_deltas(before: Snapshot, after: Snapshot): ITickDeltas {
  const flow_edge = multiset_diff(before.flow_edge, after.flow_edge);
  const flow_reach = multiset_diff(before.flow_reach, after.flow_reach);
  const resolved_call_edge = multiset_diff(before.resolved_call_edge, after.resolved_call_edge);
  return {
    rels: [
      { rel: "flow_edge", add: flow_edge.add, del: flow_edge.del },
      { rel: "flow_reach", add: flow_reach.add, del: flow_reach.del },
      { rel: "resolved_call_edge", add: resolved_call_edge.add, del: resolved_call_edge.del },
    ],
    carry_pending: false,
  };
}

function run_naive_tick(seam: ISqlSeam, arrivals: IArrivalBatch): Observable<ITickDeltas> {
  return read_snapshot(seam).pipe(
    concatMap((before) => apply_arrivals(seam, arrivals).pipe(map(() => before))),
    concatMap((before) => recompute_levels(seam).pipe(map(() => before))),
    concatMap((before) => read_snapshot(seam).pipe(map((after) => build_deltas(before, after)))),
  );
  // flagship_flow_reach_over_batched_resolved_edges: no edge rules -- absorb arrivals, recompute levels, diff.
}

const INCREMENTAL_PROGRAM_SAFE = true;
const RECONCILE_EVERY_TICK = false;
const EMITTER_MODE = process.env.SPREFA_TSV2_EMITTER_MODE === "naive" ? "naive" : "incremental";

const SUBSCRIBE_PRUNE = SubscribeCone.mode();
const SUBSCRIBE_PRUNE_TICK_PATH: string = EMITTER_MODE;
if (SUBSCRIBE_PRUNE === "on" && SUBSCRIBE_PRUNE_TICK_PATH !== "incremental") {
  throw new Error(`subscribe_prune_unsupported_tick_path ${SUBSCRIBE_PRUNE_TICK_PATH}`);
}
const SUBSCRIBED_RELATIONS = SubscribeCone.relations(SUBSCRIBE_PRUNE, INCREMENTAL_RELATIONS, subscribed_rels, arrival_targets);
const SUBSCRIBED_EDGE_STATEMENTS = SubscribeCone.edges(SUBSCRIBE_PRUNE, INCREMENTAL_EDGE_STATEMENTS, subscribed_rels);
const SUBSCRIBED_LEVEL_STATEMENTS = SubscribeCone.levels(SUBSCRIBE_PRUNE, INCREMENTAL_LEVEL_STATEMENTS, subscribed_rels);
const SUBSCRIBED_BOOT = SubscribeCone.boot(SUBSCRIBE_PRUNE, boot, subscribed_rels, arrival_targets);

function run_incremental_tick(seam: ISqlSeam, arrivals: IArrivalBatch): Observable<ITickDeltas> {
  return IncrementalRuntime.prepare_tick(seam, SUBSCRIBED_RELATIONS).pipe(
    concatMap(() => IncrementalRuntime.apply_arrivals(seam, arrivals, SUBSCRIBED_RELATIONS)),
    concatMap(() => IncrementalRuntime.apply_levels_before_edges(seam, SUBSCRIBED_LEVEL_STATEMENTS, SUBSCRIBED_RELATIONS)),
    concatMap(() => IncrementalRuntime.apply_edges(seam, SUBSCRIBED_EDGE_STATEMENTS, SUBSCRIBED_RELATIONS)),
    concatMap(() => of(undefined)),
    concatMap(() => of(undefined)),
    concatMap(() => IncrementalRuntime.recompute_levels_after_edges(seam, SUBSCRIBED_LEVEL_STATEMENTS, SUBSCRIBED_RELATIONS, RECONCILE_EVERY_TICK)),
    concatMap(() => IncrementalRuntime.read_boundary(seam, SUBSCRIBED_RELATIONS)),
    concatMap((rels) => IncrementalRuntime.promote_frontiers(seam, SUBSCRIBED_RELATIONS).pipe(
      map((carry_pending): ITickDeltas => ({ rels, carry_pending })),
    )),
  );
}

function run_tick(seam: ISqlSeam, arrivals: IArrivalBatch): Observable<ITickDeltas> {
  arrivals = validate_arrivals(arrivals);
  if (EMITTER_MODE === "naive" || !INCREMENTAL_PROGRAM_SAFE) {
    return run_naive_tick(seam, arrivals);
  }
  return run_incremental_tick(seam, arrivals);
}

export const incremental_plan: IIncrementalProgramPlan = {
  safe: INCREMENTAL_PROGRAM_SAFE,
  reconcile_every_tick: RECONCILE_EVERY_TICK,
  retraction_guard: "recursive-cte-reseed",
  relations: INCREMENTAL_RELATIONS,
  edges: INCREMENTAL_EDGE_STATEMENTS,
  levels: INCREMENTAL_LEVEL_STATEMENTS,
};

export const program: IGenProgramWithBoot = {
  name: "flagship_flow_reach_over_batched_resolved_edges",
  ddl,
  rel_columns,
  rel_column_types,
  arrival_targets,
  boot: SUBSCRIBED_BOOT,
  final_select,
  host_plans,
  bind_plans,
  query_plans,
  subscribed_rels,
  rel_catalog,
  unsupported_execution,
  tick: run_tick,
};
